func TestCallLogsService_AddRecording(t *testing.T) {
	t.Parallel()

	audio := []byte("test-audio")

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/callLogs/log-1/recordings" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("X-Test"); got != "recording" {
			t.Fatalf("unexpected header X-Test: %q", got)
		}

		contentType := r.Header.Get("Content-Type")
		mediaType, params, err := mime.ParseMediaType(contentType)
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		if mediaType != "multipart/form-data" {
			t.Fatalf("unexpected media type: %s", mediaType)
		}

		reader := multipart.NewReader(r.Body, params["boundary"])
		part, err := reader.NextPart()
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		if part.FormName() != "file" {
			t.Fatalf("unexpected form name: %s", part.FormName())
		}
		if part.FileName() != "recording.mp3" {
			t.Fatalf("unexpected filename: %s", part.FileName())
		}
		payload, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		if !bytes.Equal(payload, audio) {
			t.Fatalf("unexpected payload: %q", payload)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true}`))
	}))
	t.Cleanup(srv.Close)

	client, err := NewClient(pipedrive.Config{BaseURL: srv.URL, HTTPClient: srv.Client()})
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}

	ok, err := client.CallLogs.AddRecording(
		context.Background(),
		CallLogID("log-1"),
		"recording.mp3",
		bytes.NewReader(audio),
		WithCallLogsRequestOptions(pipedrive.WithHeader("X-Test", "recording")),
	)
	if err != nil {
		t.Fatalf("AddRecording error: %v", err)
	}
	if !ok {
		t.Fatalf("expected recording success")
	}
}

func TestCallLogsService_AddRecording_SourceReadError(t *testing.T) {
	t.Parallel()

	client, err := NewClient(pipedrive.Config{
		BaseURL: "https://example.test",
		HTTPClient: &http.Client{Transport: roundTripperFunc(func(req *http.Request) (*http.Response, error) {
			defer req.Body.Close()
			_, err := io.ReadAll(req.Body)
			return nil, err
		})},
	})
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}

	_, err = client.CallLogs.AddRecording(
		context.Background(),
		CallLogID("log-1"),
		"recording.mp3",
		&errReader{err: errors.New("boom")},
	)
	if err == nil || !strings.Contains(err.Error(), "boom") {
		t.Fatalf("expected source read error, got %v", err)
	}
}

type roundTripperFunc func(*http.Request) (*http.Response, error)

func (f roundTripperFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return f(req)
}

type errReader struct {
	err error
}

func (r *errReader) Read(p []byte) (int, error) {
	return 0, r.err
}

package multipartbody

import (
	"bytes"
	"fmt"
	"io"
	"mime/multipart"
)

// NewFile encodes src as a multipart/form-data body with a single file part.
//
// It returns the Content-Type header value and a *bytes.Reader over the
// encoded body. Because *bytes.Reader is recognized by http.NewRequest,
// the resulting request automatically gets a working GetBody, which
// makes retries (e.g. on 429 / 5xx) safe without any extra wiring.
func NewFile(fieldName, fileName string, src io.Reader) (string, *bytes.Reader, error) {
	if fieldName == "" {
		return "", nil, fmt.Errorf("multipart field name is required")
	}
	if fileName == "" {
		return "", nil, fmt.Errorf("multipart file name is required")
	}
	if src == nil {
		return "", nil, fmt.Errorf("multipart file content is required")
	}

	var buf bytes.Buffer
	writer := multipart.NewWriter(&buf)

	part, err := writer.CreateFormFile(fieldName, fileName)
	if err != nil {
		return "", nil, fmt.Errorf("create multipart file: %w", err)
	}
	if _, err := io.Copy(part, src); err != nil {
		return "", nil, fmt.Errorf("write multipart file: %w", err)
	}
	if err := writer.Close(); err != nil {
		return "", nil, fmt.Errorf("close multipart writer: %w", err)
	}

	return writer.FormDataContentType(), bytes.NewReader(buf.Bytes()), nil
}
